function playerName(){const value=$("playerName").value.trim();if(!value){$("homeError").textContent="Önce adını yaz.";return null;}localStorage.setItem("head-ball-name",value);return value;}
$("playerName").value=localStorage.getItem("head-ball-name")||"";
const careerKey=(mode)=>`head-ball-career-${mode}`;
const LEAGUE_CLUBS=["SENİN TAKIMIN","RUMELİ FK","HENRY FORD SK","KOÇ POYRAZ","SAAT KULESİ","ORMAN XI","KAMPÜS 93","KUZEY TRİBÜNÜ"];
const DIFFICULTY_LABELS={easy:"RAHAT",normal:"DENGELİ",hard:"USTA"},LEAGUE_TEAM_OPTIONS=[4,6,8],LEAGUE_LEG_OPTIONS=[1,2],CUP_ROUND_OPTIONS=[2,3,4];
function normalizeCareerConfig(mode,config={}){const difficulty=["easy","normal","hard"].includes(config.difficulty)?config.difficulty:"normal";if(mode==="season")return{teamCount:LEAGUE_TEAM_OPTIONS.includes(Number(config.teamCount))?Number(config.teamCount):8,legs:LEAGUE_LEG_OPTIONS.includes(Number(config.legs))?Number(config.legs):1,difficulty};return{rounds:CUP_ROUND_OPTIONS.includes(Number(config.rounds))?Number(config.rounds):3,difficulty};}
function leagueSchedule(teamCount=8,legs=1){const order=Array.from({length:teamCount},(_,index)=>index),first=[];for(let round=0;round<teamCount-1;round++){const pairs=[];for(let index=0;index<teamCount/2;index++){const a=order[index],b=order[teamCount-1-index];pairs.push(round%2&&index===0?[b,a]:[a,b]);}first.push(pairs);order.splice(1,0,order.pop());}return legs===2?first.concat(first.map((pairs)=>pairs.map(([a,b])=>[b,a]))):first;}
function freshTable(teamCount=8){return LEAGUE_CLUBS.slice(0,teamCount).map((name,id)=>({id,name,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}));}
function leagueMatchCount(career){return(career.config.teamCount-1)*career.config.legs;}
function newCareer(mode,config={}){const normalized=normalizeCareerConfig(mode,config);return mode==="season"?{mode,config:normalized,played:0,table:freshTable(normalized.teamCount),character:null,rules:null,seed:Math.floor(Math.random()*2147483646)+1,complete:false}:{mode,config:normalized,round:0,wins:0,eliminated:false,champion:false,complete:false};}
function normalizeCareer(career,mode){if(!career||career.mode!==mode)return newCareer(mode);career.config=normalizeCareerConfig(mode,career.config);if(mode==="season"){const total=leagueMatchCount(career);career.played=Math.min(total,Math.max(0,career.played||0));career.seed=career.seed||1357911;if(!Array.isArray(career.table)||career.table.length!==career.config.teamCount){career.table=freshTable(career.config.teamCount);const me=career.table[0];me.p=career.played;me.w=career.wins||0;me.l=career.losses||0;me.d=Math.max(0,me.p-me.w-me.l);me.gf=career.goalsFor||0;me.ga=career.goalsAgainst||0;me.pts=career.points??me.w*3+me.d;const schedule=leagueSchedule(career.config.teamCount,career.config.legs);for(let round=0;round<career.played;round++)for(const [a,b] of schedule[round])if(a!==0&&b!==0){const [ga,gb]=simulateCpuScore(career);applyLeagueResult(career,a,b,ga,gb);}}career.character=Number.isInteger(career.character)?career.character:null;career.rules=career.rules||null;career.complete=career.played>=total;}else{career.round=Math.min(career.config.rounds,Math.max(0,career.round||0));career.wins=Math.min(career.config.rounds,Math.max(0,career.wins||career.round));career.eliminated=!!career.eliminated;career.champion=career.round>=career.config.rounds;career.complete=career.eliminated||career.champion;}return career;}
function loadCareer(mode){try{return normalizeCareer(JSON.parse(localStorage.getItem(careerKey(mode))),mode);}catch{return newCareer(mode);}}
function saveCareer(career){if(career)localStorage.setItem(careerKey(career.mode),JSON.stringify(career));}
function sortedTable(career){return [...career.table].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf||a.name.localeCompare(b.name,"tr"));}
function cupRoundName(career){const remaining=career.config.rounds-career.round;return{4:"SON 16",3:"ÇEYREK FİNAL",2:"YARI FİNAL",1:"FİNAL"}[remaining]||"TAMAMLANDI";}
function careerText(career){if(!career)return "";const difficulty=DIFFICULTY_LABELS[career.config.difficulty];if(career.mode==="season"){const me=career.table[0],rank=sortedTable(career).findIndex((team)=>team.id===0)+1,total=leagueMatchCount(career);return `<b>KAMPÜS LİGİ</b> • ${career.played}/${total} MAÇ • ${rank}. SIRA • ${me.pts} PUAN • ${difficulty}`;}return `<b>KAMPÜS KUPASI</b> • ${career.champion?"ŞAMPİYON":career.eliminated?"ELENDİN":cupRoundName(career)} • ${career.wins}/${career.config.rounds} GALİBİYET • ${difficulty}`;}
function leagueRandom(career){career.seed=career.seed*48271%2147483647;return career.seed/2147483647;}
function applyLeagueResult(career,a,b,goalsA,goalsB){const home=career.table[a],away=career.table[b];home.p++;away.p++;home.gf+=goalsA;home.ga+=goalsB;away.gf+=goalsB;away.ga+=goalsA;if(goalsA>goalsB){home.w++;away.l++;home.pts+=3;}else if(goalsB>goalsA){away.w++;home.l++;away.pts+=3;}else{home.d++;away.d++;home.pts++;away.pts++;}}
function simulateCpuScore(career){const first=Math.floor(leagueRandom(career)*4),second=Math.floor(leagueRandom(career)*4);return[first,second];}
function completeLeagueRound(career,ours,theirs){const schedule=leagueSchedule(career.config.teamCount,career.config.legs),pairs=schedule[career.played];for(const [a,b] of pairs){if(a===0)applyLeagueResult(career,a,b,ours,theirs);else if(b===0)applyLeagueResult(career,a,b,theirs,ours);else{const [ga,gb]=simulateCpuScore(career);applyLeagueResult(career,a,b,ga,gb);}}career.played++;career.complete=career.played>=schedule.length;}
function showLeagueTable(){const career=activeCareer?.mode==="season"?activeCareer:loadCareer("season"),schedule=leagueSchedule(career.config.teamCount,career.config.legs),next=schedule[career.played]?.find((pair)=>pair.includes(0)),opponent=next?career.table[next[0]===0?next[1]:next[0]].name:"LİG TAMAMLANDI",fighter=Number.isInteger(career.character)?roster[career.character].name:"İLK MAÇTA SEÇİLECEK",rules=career.rules?`${career.rules.duration} SN • İLK ${career.rules.goalLimit} GOL`:"İLK MAÇTA BELİRLENECEK";$("leagueFormat").textContent=`${career.config.legs===2?"ÇİFT":"TEK"} DEVRE • ${career.config.teamCount} TAKIM • ${DIFFICULTY_LABELS[career.config.difficulty]}`;$("leagueFixture").innerHTML=`<b>${career.complete?"SEZON SONU":`SIRADAKİ: ${opponent}`}</b> • KARAKTER: ${fighter} • KURALLAR: ${rules}`;const rows=sortedTable(career);$("leagueTable").innerHTML=`<div class="league-row head"><span>#</span><span>TAKIM</span><span>O</span><span>G</span><span>B</span><span>M</span><span class="hide-mobile">AV</span><span>PUAN</span></div>`+rows.map((team,index)=>`<div class="league-row ${team.id===0?"user":""}"><span class="rank">${index+1}</span><span class="club">${team.name}</span><span>${team.p}</span><span>${team.w}</span><span>${team.d}</span><span>${team.l}</span><span class="hide-mobile">${team.gf-team.ga>0?"+":""}${team.gf-team.ga}</span><span class="pts">${team.pts}</span></div>`).join("");$("leagueOverlay").classList.remove("hidden");}
function renderCareerPreview(){const season=loadCareer("season"),cup=loadCareer("cup");$("careerPreview").innerHTML=`${careerText(season)}<br>${careerText(cup)}`;}
function showModeMenu(id){$("modeRoot").classList.toggle("hidden",!!id);$("singleMenu").classList.toggle("hidden",id!=="singleMenu");$("multiMenu").classList.toggle("hidden",id!=="multiMenu");$("homeError").textContent="";if(id==="singleMenu")renderCareerPreview();}
function careerHasProgress(career){return career.mode==="season"?career.played>0:career.round>0||career.eliminated||career.champion;}
let pendingCareerMode=null,pendingCareerConfig=null;
function renderCareerSetup(){const mode=pendingCareerMode,config=pendingCareerConfig,isSeason=mode==="season";$("careerSetupKicker").textContent=isSeason?"KAMPÜS LİGİ":"KAMPÜS KUPASI";$("careerSetupTitle").textContent=isSeason?"Lig formatını kur":"Kupa yolunu kur";const option=(value,current,label,copy,key)=>`<button class="career-option ${value===current?"selected":""}" data-career-key="${key}" data-career-value="${value}"><b>${label}</b><span>${copy}</span></button>`;$("careerSetupFields").innerHTML=isSeason?`<div><b>TAKIM SAYISI</b><div class="career-options">${option(4,config.teamCount,"4 TAKIM","3 veya 6 maç","teamCount")}${option(6,config.teamCount,"6 TAKIM","5 veya 10 maç","teamCount")}${option(8,config.teamCount,"8 TAKIM","7 veya 14 maç","teamCount")}</div></div><div><b>FİKSTÜR</b><div class="career-options two">${option(1,config.legs,"TEK DEVRE","Her rakiple bir kez","legs")}${option(2,config.legs,"ÇİFT DEVRE","Rövanş maçları dahil","legs")}</div></div>`:`<div><b>TURNUVA BOYUTU</b><div class="career-options">${option(2,config.rounds,"4 TAKIM","2 maç • Yarı finalden","rounds")}${option(3,config.rounds,"8 TAKIM","3 maç • Çeyrek finalden","rounds")}${option(4,config.rounds,"16 TAKIM","4 maç • Son 16'dan","rounds")}</div></div>`;$("careerDifficultyOptions").innerHTML=option("easy",config.difficulty,"RAHAT","Daha yavaş karar verir","difficulty")+option("normal",config.difficulty,"DENGELİ","Önerilen adil seviye","difficulty")+option("hard",config.difficulty,"USTA","Daha hızlı okur ve hamle yapar","difficulty");const total=isSeason?(config.teamCount-1)*config.legs:config.rounds;$("careerSetupSummary").textContent=isSeason?`${config.teamCount} TAKIM • ${config.legs===2?"ÇİFT":"TEK"} DEVRE • ${total} MAÇ • ${DIFFICULTY_LABELS[config.difficulty]}`:`${2**config.rounds} TAKIM • ${config.rounds} ELEME MAÇI • ${DIFFICULTY_LABELS[config.difficulty]}`;document.querySelectorAll("[data-career-key]").forEach((button)=>button.onclick=()=>{const key=button.dataset.careerKey,raw=button.dataset.careerValue;pendingCareerConfig[key]=["difficulty"].includes(key)?raw:Number(raw);renderCareerSetup();});}
function openCareerSetup(mode){if(!playerName())return;const current=loadCareer(mode);pendingCareerMode=mode;pendingCareerConfig=normalizeCareerConfig(mode,current.config);renderCareerSetup();$("careerSetupOverlay").classList.remove("hidden");}
function startSolo(competition){const name=playerName();if(!name)return;activeCareer=competition==="quick"?null:loadCareer(competition);saveCareer(activeCareer);socket.emit("createSolo",{name,competition,rules:activeCareer?.rules,character:activeCareer?.character,difficulty:activeCareer?.config?.difficulty||"normal"},joined);}
function chooseCareer(mode){const career=loadCareer(mode);if(!career.complete&&careerHasProgress(career))startSolo(mode);else openCareerSetup(mode);}
function resetCareer(mode){const label=mode==="season"?"ligi":"kupayı";if(!window.confirm(`${label[0].toUpperCase()+label.slice(1)} sıfırlansın mı? Tüm ilerleme kalıcı olarak silinecek.`))return;localStorage.setItem(careerKey(mode),JSON.stringify(newCareer(mode)));$("leagueOverlay").classList.add("hidden");$("careerSetupOverlay").classList.add("hidden");if(activeCareer?.mode===mode)quitToMenu();else renderCareerPreview();toast(`${mode==="season"?"Lig":"Kupa"} sıfırlandı. Yeni ayarlarını seçebilirsin.`);}
