$("quickOnlineBtn").onclick=()=>{const name=playerName();if(name){activeCareer=null;socket.emit("quickMatch",{name},(result)=>{joined(result);if(result?.waiting)toast("Rakip aranıyor; bu sırada karakterini seçebilirsin.");});}};
$("createBtn").onclick=()=>{const name=playerName();if(name){activeCareer=null;socket.emit("createRoom",{name},joined);}};
$("joinBtn").onclick=()=>{const name=playerName();if(name){activeCareer=null;socket.emit("joinRoom",{name,code:$("roomCode").value},joined);}};
$("roomCode").onkeydown=(event)=>{if(event.key==="Enter")$("joinBtn").click();};
function joined(result){if(!result.ok){$("homeError").textContent=result.error||"Bağlanılamadı.";return;}saveSession(result);room=result.room;if(room.playMode==="single"&&["season","cup"].includes(room.competition))activeCareer=loadCareer(room.competition);show("lobby");renderLobby();}
function saveSession(result){if(result?.sessionToken&&result?.room?.code)localStorage.setItem("head-ball-session",JSON.stringify({code:result.room.code,token:result.sessionToken}));}
function enterMatch(next,resumed=false){state=next;setArenaGeometry(next);lastStateReceived=performance.now();renderPlayers.fill(null);next.players.forEach((player)=>renderPlayers[player.side]={...player});renderBall={...next.ball};ballAngle=0;myCharacter=room?.selections?.[mySide]??playerBySide(mySide,next.players)?.character??0;$("endOverlay").classList.add("hidden");$("resetMatchCareer").classList.toggle("hidden",!activeCareer);show("game");updateHud();setMoveCard();if(next.phase==="intro"){renderIntro(next);if(!resumed){setMusicLevel(MATCH_MUSIC_LEVEL);ensureAudio();playIntro();}}else $("versusIntro").classList.add("hidden");if(next.phase==="matchOver"&&next.winner!==null){$("winnerText").textContent=`${next.winner===0?"MAVİ":"KIRMIZI"} TAKIM KAZANDI`;$("finalScore").textContent=`${next.score[0]} — ${next.score[1]}`;$("endOverlay").classList.remove("hidden");}}
function tryResume(){let saved;try{saved=JSON.parse(localStorage.getItem("head-ball-session"));}catch{localStorage.removeItem("head-ball-session");}if(!saved?.code||!saved?.token){$("connectionStatus").classList.remove("show");return;}socket.emit("resumeSession",saved,(result)=>{if(!result?.ok){if(!room)localStorage.removeItem("head-ball-session");$("connectionStatus").classList.remove("show");return;}saveSession(result);room=result.room;if(room.playMode==="single"&&["season","cup"].includes(room.competition))activeCareer=loadCareer(room.competition);const me=room.members.find((member)=>member.id===socket.id);mySide=me?.side??null;myCharacter=mySide===null?null:room.selections[mySide];$("connectionStatus").classList.remove("show");if(result.state)enterMatch(result.state,true);else{show("lobby");renderLobby();}});}
socket.on("connect",tryResume);
socket.on("disconnect",()=>{$("connectionStatus").classList.add("show");});

socket.on("lobby",(next)=>{room=next;setArenaGeometry(next);const me=next.members.find((member)=>member.id===socket.id);mySide=me?.side??null;myCharacter=mySide===null?null:next.selections[mySide];if(next.phase==="lobby"){show("lobby");renderLobby();}else if($("lobby").classList.contains("active"))renderLobby();});
socket.on("matchStarted",(next)=>enterMatch(next));
socket.on("state",(next)=>{state=next;setArenaGeometry(next);lastStateReceived=performance.now();updateHud();if(next.phase==="intro")renderIntro(next);});
socket.on("introEnded",()=>{$("versusIntro").classList.add("hidden");announce("BAŞLA!");playWhistle();});
