function ensureAudio(){if(audioCtx){if(audioCtx.state==="suspended")audioCtx.resume();playMusic();return;}audioCtx=new(window.AudioContext||window.webkitAudioContext)();musicGain=audioCtx.createGain();musicCompressor=audioCtx.createDynamicsCompressor();sfxGain=audioCtx.createGain();musicGain.gain.value=musicOn?musicGainValue():0;musicCompressor.threshold.value=-13;musicCompressor.knee.value=18;musicCompressor.ratio.value=4;musicCompressor.attack.value=.008;musicCompressor.release.value=.2;sfxGain.gain.value=.2;musicElement=new Audio("/assets/stadium-theme.mp3");musicElement.loop=true;musicElement.preload="auto";musicElement.volume=1;musicSource=audioCtx.createMediaElementSource(musicElement);musicSource.connect(musicGain);musicGain.connect(musicCompressor);musicCompressor.connect(audioCtx.destination);sfxGain.connect(audioCtx.destination);playMusic();}
function tone(freq,at,duration,type,gain,destination=sfxGain){if(!audioCtx)return;const oscillator=audioCtx.createOscillator(),volume=audioCtx.createGain();oscillator.type=type;oscillator.frequency.setValueAtTime(freq,at);volume.gain.setValueAtTime(.0001,at);volume.gain.exponentialRampToValueAtTime(gain,at+.012);volume.gain.exponentialRampToValueAtTime(.0001,at+duration);oscillator.connect(volume);volume.connect(destination);oscillator.start(at);oscillator.stop(at+duration+.02);}
function noise(at,duration,gain,frequency=1000,destination=sfxGain){if(!audioCtx)return;const length=Math.floor(audioCtx.sampleRate*duration),buffer=audioCtx.createBuffer(1,length,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length);const source=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter(),volume=audioCtx.createGain();source.buffer=buffer;filter.type="highpass";filter.frequency.value=frequency;volume.gain.setValueAtTime(gain,at);volume.gain.exponentialRampToValueAtTime(.0001,at+duration);source.connect(filter);filter.connect(volume);volume.connect(destination);source.start(at);}
function playHeader(speed,special){ensureAudio();const now=audioCtx.currentTime;tone(special?88:115,now,.16,"sawtooth",.22,sfxGain);tone(Math.min(520,170+speed*.25),now,.08,"square",.13,sfxGain);noise(now,special?.17:.09,special?.18:.1,500);}
function playGoal(){ensureAudio();const now=audioCtx.currentTime;[261.63,329.63,392,523.25].forEach((frequency,index)=>tone(frequency,now+index*.09,.42,"square",.17,sfxGain));noise(now,.5,.18,650);}
function playWhistle(){ensureAudio();const now=audioCtx.currentTime;tone(1900,now,.18,"sine",.15,sfxGain);tone(2300,now+.05,.19,"sine",.12,sfxGain);}
function playSpecial(){ensureAudio();const now=audioCtx.currentTime;tone(95,now,.34,"sawtooth",.24,sfxGain);tone(760,now+.04,.3,"sine",.16,sfxGain);noise(now,.24,.12,850);}
function playDash(){ensureAudio();const now=audioCtx.currentTime;tone(210,now,.12,"sine",.1,sfxGain);tone(650,now+.02,.1,"sine",.08,sfxGain);}
function playJump(){ensureAudio();const now=audioCtx.currentTime;tone(220,now,.1,"sine",.07,sfxGain);tone(430,now+.03,.11,"sine",.06,sfxGain);}
function playVictory(){ensureAudio();const now=audioCtx.currentTime;[196,246.94,293.66,392,493.88,587.33].forEach((frequency,index)=>tone(frequency,now+index*.11,.5,"square",.13,sfxGain));}
function playIntro(){ensureAudio();const now=audioCtx.currentTime;tone(82,now,.55,"sawtooth",.13,sfxGain);tone(164,now+.16,.42,"square",.08,sfxGain);noise(now+.08,.35,.065,720);}
document.addEventListener("pointerdown",ensureAudio,{once:true});
function updateAudioUi(){$("audioToggle").textContent=musicOn?"♫ MÜZİK: AÇIK":"♫ MÜZİK: KAPALI";$("audioToggle").classList.toggle("muted",!musicOn);$("musicVolume").value=musicLevel;$("musicVolumeValue").textContent=`%${musicLevel}`;}
function setMusicLevel(value){musicLevel=Math.max(0,Math.min(100,Number(value)));localStorage.setItem("head-ball-music-volume",String(musicLevel));if(audioCtx&&musicOn)musicGain.gain.setTargetAtTime(musicGainValue(),audioCtx.currentTime,.035);updateAudioUi();}
$("audioToggle").onclick=()=>{ensureAudio();musicOn=!musicOn;localStorage.setItem("head-ball-music-on",musicOn?"1":"0");musicGain.gain.setTargetAtTime(musicOn?musicGainValue():0,audioCtx.currentTime,.04);if(musicOn)playMusic();else musicElement?.pause();updateAudioUi();};
$("musicVolume").oninput=(event)=>setMusicLevel(event.target.value);
updateAudioUi();

const canvas=$("arena"),ctx=canvas.getContext("2d"),PLAYER_LEFT=185;
const lerp=(from,to,amount)=>from+(to-from)*amount,clamp=(value,min,max)=>Math.max(min,Math.min(max,value)),smooth=(rate,dt)=>1-Math.exp(-rate*dt);
function createImpact(x,y,color,speed,special){const count=special?42:speed>700?32:20;for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,velocity=100+Math.random()*(special?520:340);particles.push({kind:"spark",x,y,vx:Math.cos(angle)*velocity,vy:Math.sin(angle)*velocity,life:.25+Math.random()*.3,max:.55,color:special?"#caff36":color,size:special?5:3});}particles.push({kind:"ring",x,y,vx:0,vy:0,life:.38,max:.38,color,size:special?110:75});}
function createDust(x,y){for(let i=0;i<14;i++)particles.push({kind:"dust",x:x+(Math.random()-.5)*45,y:y-5,vx:(Math.random()-.5)*180,vy:-30-Math.random()*90,life:.35+Math.random()*.3,max:.65,color:"#ded5c0",size:7+Math.random()*13});}
function createGoalBurst(x,y,side){const originX=side===0?WORLD_WIDTH-100:100;for(let i=0;i<90;i++){const angle=Math.random()*Math.PI*2,velocity=150+Math.random()*650;particles.push({kind:i%4===0?"confetti":"spark",x:originX,y:470+Math.random()*80,vx:Math.cos(angle)*velocity,vy:Math.sin(angle)*velocity-180,life:.7+Math.random()*.8,max:1.5,color:["#caff36","#42e5ef","#ffcf48","#ff405d"][i%4],size:4+Math.random()*6});}}
function syncRender(dt){if(!state?.players)return;for(const source of state.players){let target=renderPlayers[source.side];if(!target){renderPlayers[source.side]={...source};continue;}const oldX=target.x,oldY=target.y;Object.assign(target,source);const elapsed=Math.min(.08,(performance.now()-lastStateReceived)/1000),amount=smooth(19,dt);target.x=lerp(oldX,source.x+source.vx*elapsed,amount);target.y=lerp(oldY,Math.min(610,source.y+source.vy*elapsed),amount);if(source.actionClock>0)target.actionClock=Math.max(0,source.actionClock-elapsed);}
  if(state.ball){if(!renderBall)renderBall={...state.ball};else{const oldX=renderBall.x,oldY=renderBall.y;Object.assign(renderBall,state.ball);const elapsed=Math.min(.075,(performance.now()-lastStateReceived)/1000),amount=smooth(21,dt);renderBall.x=lerp(oldX,state.ball.x+state.ball.vx*elapsed,amount);renderBall.y=lerp(oldY,state.ball.y+state.ball.vy*elapsed,amount);}}
}
function drawStage(index,now){const baseIndex=stageBaseIndex(index),period=stagePeriod(index),image=stageImgs[baseIndex]||stageImgs[0];if(image.complete&&image.naturalWidth)ctx.drawImage(image,0,0,WORLD_WIDTH,720);else{ctx.fillStyle="#102a30";ctx.fillRect(0,0,WORLD_WIDTH,720);}ctx.fillStyle=period.overlay;ctx.fillRect(0,0,WORLD_WIDTH,720);const shade=ctx.createLinearGradient(0,0,0,720);shade.addColorStop(0,"rgba(2,13,18,.12)");shade.addColorStop(.72,"rgba(2,14,16,.08)");shade.addColorStop(1,"rgba(1,8,10,.64)");ctx.fillStyle=shade;ctx.fillRect(0,0,WORLD_WIDTH,720);
  if(baseIndex===1){ctx.strokeStyle="rgba(180,230,255,.27)";ctx.lineWidth=1.2;for(const drop of environment){const y=(drop.y+now*.22*drop.speed)%760-20,x=(drop.x+now*.017*drop.speed)%(WORLD_WIDTH+40)-20;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-6,y+15+drop.size*2);ctx.stroke();}}else if(baseIndex===5){for(const flake of environment){const y=(flake.y+now*.035*flake.speed)%750-15,x=(flake.x+Math.sin(now*.001+flake.y)*26)%WORLD_WIDTH;ctx.globalAlpha=.28+(flake.size%3)*.13;ctx.fillStyle="#f4fbff";ctx.beginPath();ctx.arc(x,y,flake.size*.72,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}else{for(let i=0;i<45;i++){const mote=environment[i],x=(mote.x+Math.sin(now*.0004+i)*30)%WORLD_WIDTH,y=(mote.y-now*.007*mote.speed+720)%720;ctx.globalAlpha=baseIndex===2?.23:baseIndex===4?.16:.11;ctx.fillStyle=baseIndex===2?"#e69a4f":baseIndex===4?"#ffd47a":"#fff3b5";ctx.beginPath();ctx.arc(x,y,mote.size*.65,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
  ctx.fillStyle="rgba(16,72,56,.56)";ctx.fillRect(0,610,WORLD_WIDTH,110);ctx.strokeStyle="rgba(240,255,244,.62)";ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,610);ctx.lineTo(WORLD_WIDTH,610);ctx.stroke();ctx.globalAlpha=.28;ctx.setLineDash([10,12]);ctx.beginPath();ctx.moveTo(CENTER,415);ctx.lineTo(CENTER,610);ctx.stroke();ctx.moveTo(PLAYER_LEFT,450);ctx.lineTo(PLAYER_LEFT,610);ctx.moveTo(WORLD_WIDTH-PLAYER_LEFT,450);ctx.lineTo(WORLD_WIDTH-PLAYER_LEFT,610);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(CENTER,610,105,Math.PI,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}
function drawGoal(side,now){const line=side===0?92:WORLD_WIDTH-92,back=side===0?18:WORLD_WIDTH-18,wave=netWave[side],rows=8;ctx.save();ctx.strokeStyle="rgba(225,248,244,.42)";ctx.lineWidth=2;for(let i=0;i<=rows;i++){const y=GOAL_TOP+i*((610-GOAL_TOP)/rows);ctx.beginPath();ctx.moveTo(line,y);ctx.quadraticCurveTo((line+back)/2+Math.sin(now*.02+i)*wave*14,y+wave*5,back,y);ctx.stroke();}for(let i=0;i<=5;i++){const t=i/5,x=lerp(line,back,t);ctx.beginPath();ctx.moveTo(x,GOAL_TOP);ctx.lineTo(x,610);ctx.stroke();}ctx.strokeStyle="#f2f7eb";ctx.shadowColor="#fff";ctx.shadowBlur=9;ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(line,610);ctx.lineTo(line,GOAL_TOP);ctx.lineTo(back,GOAL_TOP);ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle=side===0?"#42e5ef":"#ff405d";ctx.lineWidth=4;ctx.stroke();ctx.restore();netWave[side]*=.94;}
function drawPlayer(player,now){const image=fighterImgs[(roster[player.character]?.asset||1)-1],air=!player.onGround,crouch=!!player.crouching||player.action==="crouch",run=player.action==="run",dash=player.action==="dash",header=player.action==="header"||player.action==="special",phase=player.actionDuration?1-player.actionClock/player.actionDuration:0,bob=crouch?0:run?Math.sin(now*.016+player.side*Math.PI)*5:Math.sin(now*.003+player.side)*1.7;let lean=clamp(player.vx/850,-.14,.14);if(header)lean+=player.facing*Math.sin(clamp(phase,0,1)*Math.PI)*.24;if(air)lean+=clamp(player.vx/1100,-.08,.08);const h=PLAYER_DRAW_HEIGHT,w=(image.naturalWidth||320)/(image.naturalHeight||500)*h,scaleY=crouch?.82:air?1.06:header?.95:1,scaleX=crouch?1.08:dash?1.12:header?1.08:1;
  ctx.save();ctx.translate(player.x,610);ctx.globalAlpha=.3;ctx.fillStyle="#000";ctx.beginPath();ctx.ellipse(0,0,air?35:53,10,0,0,Math.PI*2);ctx.fill();ctx.restore();
  if(dash){for(let i=3;i>=1;i--){ctx.save();ctx.translate(player.x-player.vx*.035*i,player.y+bob);if(player.facing<0)ctx.scale(-1,1);ctx.rotate(lean);ctx.globalAlpha=.06*i;ctx.globalCompositeOperation="screen";ctx.drawImage(image,-w/2,-h,w,h);ctx.restore();}}
  ctx.save();ctx.translate(player.x,player.y+bob);if(player.facing<0)ctx.scale(-1,1);ctx.rotate(lean);ctx.scale(scaleX,scaleY);if(player.specialKind){ctx.shadowColor=["#65efff","#caff36","#ff9a3d","#b56cff","#ffd43b","#ff71c6","#62ffc4","#d88cff","#d8ff38","#59c7ff","#c56a42","#ffe837","#ff7567","#ff35c8","#ffcf55","#b695ff"][player.character];ctx.shadowBlur=36;ctx.globalCompositeOperation="screen";}else{ctx.shadowColor=player.team===0?"#42e5ef":"#ff405d";ctx.shadowBlur=10;}ctx.drawImage(image,-w/2,-h,w,h);ctx.restore();
  if(header){const glow=1-Math.abs(.5-phase)*2;ctx.save();ctx.globalCompositeOperation="screen";ctx.globalAlpha=clamp(glow,0,.8);ctx.strokeStyle=player.specialKind?"#caff36":"#fff";ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=24;ctx.lineWidth=7;ctx.beginPath();ctx.arc(player.x+player.facing*31,player.y+HEAD_OFFSET,50,0,Math.PI*2);ctx.stroke();ctx.restore();}
  const campLimit=player.goalCampLimit||2.45,goalLocked=(player.goalLock||0)>0;if(goalLocked||player.goalCamp>campLimit*.65){const strength=goalLocked?1:clamp(player.goalCamp/campLimit,0,1),direction=player.team===0?1:-1;ctx.save();ctx.globalAlpha=.35+.5*strength;ctx.fillStyle=goalLocked?"#ff405d":"#ffcf48";ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=18;for(let i=0;i<3;i++){const x=player.x-direction*(64+i*23);ctx.beginPath();ctx.moveTo(x,player.y-95);ctx.lineTo(x+direction*18,player.y-108);ctx.lineTo(x+direction*18,player.y-82);ctx.closePath();ctx.fill();}if(goalLocked){ctx.globalAlpha=1;ctx.textAlign="center";ctx.font="900 11px Inter";ctx.fillStyle="#fff";ctx.shadowColor="#000";ctx.shadowBlur=7;ctx.fillText(`KALE YASAĞI ${Math.ceil(player.goalLock)}s`,player.x,player.y-260);}ctx.restore();}
  ctx.save();ctx.textAlign="center";ctx.font="800 11px Inter";ctx.fillStyle="#fff";ctx.shadowColor="#000";ctx.shadowBlur=6;ctx.fillText(player.human?player.playerName:"CPU",player.x,player.y+21);ctx.restore();}
function drawBall(ball,dt){const style=balls[ball.type],speed=Math.hypot(ball.vx,ball.vy);ballAngle+=(ball.spin+ball.vx*.008)*dt;if(speed>420){ctx.save();ctx.globalCompositeOperation="screen";for(let i=5;i>=1;i--){ctx.globalAlpha=.035*i;ctx.fillStyle=style.color;ctx.beginPath();ctx.arc(ball.x-ball.vx*.015*i,ball.y-ball.vy*.015*i,ball.radius*(1-i*.055),0,Math.PI*2);ctx.fill();}ctx.restore();}
  ctx.save();ctx.translate(ball.x,ball.y);ctx.rotate(ballAngle);ctx.shadowColor=style.color;ctx.shadowBlur=speed>650?28:12;const gradient=ctx.createRadialGradient(-ball.radius*.32,-ball.radius*.35,3,0,0,ball.radius);gradient.addColorStop(0,"#fff");gradient.addColorStop(.34,style.color);gradient.addColorStop(1,"#182128");ctx.fillStyle=gradient;ctx.beginPath();ctx.arc(0,0,ball.radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle=style.accent;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,ball.radius-3,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(-ball.radius*.4,-ball.radius*.6);ctx.lineTo(ball.radius*.38,-ball.radius*.16);ctx.lineTo(ball.radius*.12,ball.radius*.58);ctx.lineTo(-ball.radius*.5,ball.radius*.25);ctx.closePath();ctx.stroke();ctx.fillStyle=style.accent;ctx.beginPath();for(let i=0;i<5;i++){const angle=-Math.PI/2+i*Math.PI*2/5,x=Math.cos(angle)*ball.radius*.24,y=Math.sin(angle)*ball.radius*.24;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.fill();ctx.restore();}
function drawEffects(dt){for(const particle of particles){particle.life-=dt;if(particle.kind!=="ring"){particle.x+=particle.vx*dt;particle.y+=particle.vy*dt;particle.vy+=(particle.kind==="dust"?180:particle.kind==="confetti"?520:760)*dt;}const alpha=clamp(particle.life/particle.max,0,1);ctx.save();ctx.globalAlpha=alpha;if(particle.kind==="ring"){ctx.strokeStyle=particle.color;ctx.shadowColor=particle.color;ctx.shadowBlur=18;ctx.lineWidth=5*alpha;ctx.beginPath();ctx.arc(particle.x,particle.y,18+(1-alpha)*particle.size,0,Math.PI*2);ctx.stroke();}else if(particle.kind==="dust"){ctx.fillStyle=particle.color;ctx.beginPath();ctx.ellipse(particle.x,particle.y,particle.size,particle.size*.42,0,0,Math.PI*2);ctx.fill();}else if(particle.kind==="confetti"){ctx.fillStyle=particle.color;ctx.translate(particle.x,particle.y);ctx.rotate(particle.life*8);ctx.fillRect(-particle.size,-2,particle.size*2,4);}else{ctx.strokeStyle=particle.color;ctx.shadowColor=particle.color;ctx.shadowBlur=8;ctx.lineWidth=particle.size*alpha;ctx.beginPath();ctx.moveTo(particle.x,particle.y);ctx.lineTo(particle.x-particle.vx*.03,particle.y-particle.vy*.03);ctx.stroke();}ctx.restore();}for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);}
function draw(now){requestAnimationFrame(draw);const dt=clamp((now-lastFrame)/1000,0,.034);lastFrame=now;syncRender(dt);cameraShake=Math.max(0,cameraShake-dt);const shake=cameraShake>0?(cameraShake/.55)*9:0,focus=renderBall?renderBall.x+clamp(renderBall.vx*.07,-85,85):CENTER,targetCamera=clamp(focus-VIEW_WIDTH/2,0,WORLD_WIDTH-VIEW_WIDTH);cameraX=lerp(cameraX,targetCamera,smooth(4.2,dt));ctx.save();ctx.translate((Math.random()-.5)*shake-cameraX,(Math.random()-.5)*shake);drawStage(state?.stage??room?.stage??0,now);drawGoal(0,now);drawGoal(1,now);renderPlayers.filter(Boolean).forEach((player)=>drawPlayer(player,now));if(renderBall)drawBall(renderBall,dt);drawEffects(dt);ctx.restore();}
requestAnimationFrame(draw);
